import axios from 'axios';
import { environment } from 'src/environments/environment';
import * as i0 from "@angular/core";
export class TipoItemService {
    constructor() { }
    async findAll() {
        const resposta = await axios.get(environment.api_url + 'tipo-item');
        return resposta.data;
    }
    async save(tipoItemDto) {
        await axios.post(environment.api_url + 'tipo-item', tipoItemDto);
    }
    async filterSearch(search) {
        const reponse = await axios.get(environment.api_url + 'item/teste/' + search);
        return reponse.data;
    }
}
